{
  "root": "main_stack",
  "state": {
    "budget_rows": [
      {
        "category": "Accommodation",
        "cost": "€700"
      },
      {
        "category": "Food & Drink",
        "cost": "€500"
      },
      {
        "category": "Attractions",
        "cost": "€200"
      },
      {
        "category": "Local Transport",
        "cost": "€100"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "itinerary_h3",
        "day1_card",
        "day2_card",
        "day3_card",
        "day4_card",
        "day5_card",
        "budget_h3",
        "budget_table",
        "budget_total_text",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Rome: Historical Sites & Culinary Delights",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 5-day itinerary for two adults focuses on Rome's iconic historical sites and authentic local cuisine, planned for a moderate pace from September 10-14, 2024. The suggested budget of €1500 (excluding flights) covers accommodation, food, attractions, and local transport for two.",
        "variant": "body"
      },
      "children": []
    },
    "itinerary_h3": {
      "type": "Text",
      "props": {
        "text": "Five-Day Roman Holiday Itinerary",
        "variant": "h3"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_title_stack",
        "day1_image",
        "day1_morning",
        "day1_afternoon",
        "day1_food"
      ]
    },
    "day1_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day1_icon",
        "day1_title"
      ]
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "day1_title": {
      "type": "Text",
      "props": {
        "text": "Day 1: Ancient Wonders & Monti Charm",
        "variant": "h3"
      },
      "children": []
    },
    "day1_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/5/53/Colosseum_in_Rome%2C_Italy_-_April_2007.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "day1_morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Arrive in Rome, check into your accommodation, and settle in. Take a leisurely walk to get acquainted with your neighborhood.",
        "variant": "body"
      },
      "children": []
    },
    "day1_afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Immerse yourselves in ancient Rome. Visit the Colosseum (exterior or pre-booked tickets for interior) and explore the vast ruins of the Roman Forum and Palatine Hill.",
        "variant": "body"
      },
      "children": []
    },
    "day1_food": {
      "type": "Text",
      "props": {
        "text": "Food: Enjoy a traditional Roman dinner in the charming Monti district, known for its trattorias serving classic pasta dishes like Cacio e Pepe or Carbonara.",
        "variant": "body"
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_title_stack",
        "day2_morning",
        "day2_afternoon",
        "day2_food"
      ]
    },
    "day2_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day2_icon",
        "day2_title"
      ]
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg"
      },
      "children": []
    },
    "day2_title": {
      "type": "Text",
      "props": {
        "text": "Day 2: Vatican City & Trastevere's Soul",
        "variant": "h3"
      },
      "children": []
    },
    "day2_morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Cross the Tiber to Vatican City. Explore St. Peter's Basilica and its grand square. Consider ascending to the dome for panoramic city views.",
        "variant": "body"
      },
      "children": []
    },
    "day2_afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Wander through the picturesque, cobblestone streets of Trastevere. Discover hidden artisan shops and beautiful churches like Santa Maria in Trastevere.",
        "variant": "body"
      },
      "children": []
    },
    "day2_food": {
      "type": "Text",
      "props": {
        "text": "Food: Indulge in an authentic Roman dinner in Trastevere, a vibrant area famous for its lively atmosphere and traditional eateries.",
        "variant": "body"
      },
      "children": []
    },
    "day3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3_title_stack",
        "day3_morning",
        "day3_afternoon",
        "day3_food"
      ]
    },
    "day3_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day3_icon",
        "day3_title"
      ]
    },
    "day3_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/water.svg"
      },
      "children": []
    },
    "day3_title": {
      "type": "Text",
      "props": {
        "text": "Day 3: Baroque Masterpieces & Pantheon Grandeur",
        "variant": "h3"
      },
      "children": []
    },
    "day3_morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Begin with the iconic Trevi Fountain (toss a coin for a return trip!) and then stroll to the elegant Spanish Steps at Piazza di Spagna.",
        "variant": "body"
      },
      "children": []
    },
    "day3_afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Visit the magnificent Pantheon, an architectural marvel. Afterwards, relax at Piazza Navona, admiring Bernini's Fountain of Four Rivers.",
        "variant": "body"
      },
      "children": []
    },
    "day3_food": {
      "type": "Text",
      "props": {
        "text": "Food: Enjoy a leisurely lunch or dinner near the Pantheon or Campo de' Fiori, perhaps with some authentic Roman pizza or a gelato break.",
        "variant": "body"
      },
      "children": []
    },
    "day4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day4_title_stack",
        "day4_morning",
        "day4_afternoon",
        "day4_food"
      ]
    },
    "day4_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day4_icon",
        "day4_title"
      ]
    },
    "day4_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg"
      },
      "children": []
    },
    "day4_title": {
      "type": "Text",
      "props": {
        "text": "Day 4: Art & Green Retreat",
        "variant": "h3"
      },
      "children": []
    },
    "day4_morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Discover masterpieces at the Borghese Gallery and Museum (pre-booking essential). Afterwards, enjoy a relaxing stroll or a rowboat ride in the surrounding Villa Borghese Gardens.",
        "variant": "body"
      },
      "children": []
    },
    "day4_afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Explore the upscale shops and boutiques along Via del Corso or simply unwind at a local café, soaking in the Roman atmosphere.",
        "variant": "body"
      },
      "children": []
    },
    "day4_food": {
      "type": "Text",
      "props": {
        "text": "Food: Dine at a local trattoria in a neighborhood you haven't explored yet, trying different regional specialties.",
        "variant": "body"
      },
      "children": []
    },
    "day5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day5_title_stack",
        "day5_morning",
        "day5_afternoon",
        "day5_food"
      ]
    },
    "day5_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day5_icon",
        "day5_title"
      ]
    },
    "day5_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/map.svg"
      },
      "children": []
    },
    "day5_title": {
      "type": "Text",
      "props": {
        "text": "Day 5: Capitoline Views & Departure",
        "variant": "h3"
      },
      "children": []
    },
    "day5_morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Visit the Capitoline Museums (pre-booking recommended) for a deep dive into Roman art and history, or enjoy the panoramic views from the Capitoline Hill.",
        "variant": "body"
      },
      "children": []
    },
    "day5_afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Do some last-minute souvenir shopping or revisit a favorite spot. Head to the airport for your departure.",
        "variant": "body"
      },
      "children": []
    },
    "day5_food": {
      "type": "Text",
      "props": {
        "text": "Food: Enjoy a final Roman meal, perhaps a classic pizza or a quick panino before heading to the airport.",
        "variant": "body"
      },
      "children": []
    },
    "budget_h3": {
      "type": "Text",
      "props": {
        "text": "Estimated Budget (for two adults, excluding flights)",
        "variant": "h3"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "cost",
            "label": "Estimated Cost (€)"
          }
        ],
        "statePath": "/budget_rows",
        "domain": "formula",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "budget_total_text": {
      "type": "Text",
      "props": {
        "text": "Total Estimated Budget: €1500",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_colosseum",
        "button_vatican",
        "button_trastevere_food",
        "button_accommodation"
      ]
    },
    "button_colosseum": {
      "type": "Button",
      "props": {
        "label": "Book Colosseum Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.coopculture.it/en/tickets/colosseum-and-roman-forum/"
          }
        }
      },
      "children": []
    },
    "button_vatican": {
      "type": "Button",
      "props": {
        "label": "Book Vatican Tour"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.museivaticani.va/content/museivaticani/en.html"
          }
        }
      },
      "children": []
    },
    "button_trastevere_food": {
      "type": "Button",
      "props": {
        "label": "Find Restaurants in Trastevere"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tripadvisor.com/Restaurants-g187791-zfn7245089-Rome_Lazio.html"
          }
        }
      },
      "children": []
    },
    "button_accommodation": {
      "type": "Button",
      "props": {
        "label": "Book Accommodation"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.booking.com/city/it/rome.html"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_rome_tourism",
        "button_lonely_planet"
      ]
    },
    "button_rome_tourism": {
      "type": "Button",
      "props": {
        "label": "Rome Tourism Board"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.turismoroma.it/en"
          }
        }
      },
      "children": []
    },
    "button_lonely_planet": {
      "type": "Button",
      "props": {
        "label": "Lonely Planet Rome Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.lonelyplanet.com/italy/rome"
          }
        }
      },
      "children": []
    }
  }
}
